#include "bmm/storage.hpp"
#include <sqlite3.h>
#include "bmm/json.hpp"
#include <fstream>
#include <iomanip>
#include <sstream>
#include <stdexcept>
namespace bmm {
namespace { void check(int rc,sqlite3*db){if(rc!=SQLITE_OK&&rc!=SQLITE_DONE&&rc!=SQLITE_ROW)throw std::runtime_error(sqlite3_errmsg(db));} }
Storage::Storage(const std::string& path){check(sqlite3_open(path.c_str(),&db_),db_); const char*sql=R"(PRAGMA busy_timeout=5000; PRAGMA journal_mode=WAL; PRAGMA foreign_keys=ON; CREATE TABLE IF NOT EXISTS schema_version(version INTEGER NOT NULL); INSERT INTO schema_version SELECT 1 WHERE NOT EXISTS(SELECT 1 FROM schema_version); CREATE TABLE IF NOT EXISTS experiments(id INTEGER PRIMARY KEY,backend TEXT NOT NULL,seed INTEGER NOT NULL,configuration TEXT NOT NULL,generator_version TEXT NOT NULL DEFAULT 'splitmix64-v1',started_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,completed_at TEXT,status TEXT NOT NULL,pages_scanned INTEGER NOT NULL DEFAULT 0,elapsed_seconds REAL NOT NULL DEFAULT 0); CREATE TABLE IF NOT EXISTS findings(id INTEGER PRIMARY KEY,experiment_id INTEGER NOT NULL REFERENCES experiments(id),page_address TEXT NOT NULL,start_offset INTEGER,end_offset INTEGER,extracted_text TEXT,lexical_score REAL,language_score REAL,detection_method TEXT,discovered_at TEXT DEFAULT CURRENT_TIMESTAMP); CREATE TABLE IF NOT EXISTS checkpoints(experiment_id INTEGER PRIMARY KEY REFERENCES experiments(id),last_completed_work_unit INTEGER NOT NULL,updated_at TEXT DEFAULT CURRENT_TIMESTAMP); CREATE INDEX IF NOT EXISTS idx_findings_experiment ON findings(experiment_id,language_score DESC); CREATE UNIQUE INDEX IF NOT EXISTS idx_findings_identity ON findings(experiment_id,page_address,start_offset,end_offset,detection_method);)"; char*err=nullptr; if(sqlite3_exec(db_,sql,nullptr,nullptr,&err)!=SQLITE_OK){std::string e=err;sqlite3_free(err);throw std::runtime_error(e);}auto has=[&](const char*name){sqlite3_stmt*s=nullptr;check(sqlite3_prepare_v2(db_,"PRAGMA table_info(findings)",-1,&s,nullptr),db_);bool found=false;while(sqlite3_step(s)==SQLITE_ROW)if(std::string(reinterpret_cast<const char*>(sqlite3_column_text(s,1)))==name)found=true;sqlite3_finalize(s);return found;};const std::pair<const char*,const char*>cols[]={{"classification","TEXT NOT NULL DEFAULT 'WORD'"},{"word_count","INTEGER NOT NULL DEFAULT 1"},{"grammar_score","REAL NOT NULL DEFAULT 0"},{"ngram_score","REAL NOT NULL DEFAULT 0"},{"completeness_score","REAL NOT NULL DEFAULT 0"},{"semantic_score","REAL"},{"scoring_model","TEXT NOT NULL DEFAULT 'baseline-untrained'"},{"scoring_version","TEXT NOT NULL DEFAULT '1'"},{"validation_method","TEXT NOT NULL DEFAULT 'lexical'"},{"source_backend","TEXT NOT NULL DEFAULT 'local'"},{"source_mode","TEXT NOT NULL DEFAULT 'natural'"},{"verification_status","TEXT NOT NULL DEFAULT 'unverified'"}};for(auto&[name,type]:cols)if(!has(name)){std::string q="ALTER TABLE findings ADD COLUMN "+std::string(name)+" "+type;check(sqlite3_exec(db_,q.c_str(),nullptr,nullptr,nullptr),db_);}migrate_v3();}
Storage::~Storage(){if(db_)sqlite3_close(db_);}
std::int64_t Storage::create_experiment(const std::string&b,std::uint64_t seed,const std::string&cfg,const std::string&version){sqlite3_stmt*s;check(sqlite3_prepare_v2(db_,"INSERT INTO experiments(backend,seed,configuration,generator_version,status)VALUES(?,?,?,?,'running')",-1,&s,nullptr),db_);sqlite3_bind_text(s,1,b.c_str(),-1,SQLITE_TRANSIENT);sqlite3_bind_int64(s,2,static_cast<sqlite3_int64>(seed));sqlite3_bind_text(s,3,cfg.c_str(),-1,SQLITE_TRANSIENT);sqlite3_bind_text(s,4,version.c_str(),-1,SQLITE_TRANSIENT);check(sqlite3_step(s),db_);sqlite3_finalize(s);return sqlite3_last_insert_rowid(db_);}
void Storage::save_batch(std::int64_t id,const std::vector<Finding>&fs){if(fs.empty())return;bool own=sqlite3_get_autocommit(db_)!=0;if(own)check(sqlite3_exec(db_,"BEGIN",nullptr,nullptr,nullptr),db_);sqlite3_stmt*s;check(sqlite3_prepare_v2(db_,"INSERT OR IGNORE INTO findings(experiment_id,page_address,start_offset,end_offset,extracted_text,lexical_score,language_score,detection_method,classification,word_count,grammar_score,ngram_score,completeness_score,semantic_score,scoring_model,scoring_version,validation_method,source_backend,source_mode,verification_status)VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)",-1,&s,nullptr),db_);for(auto&f:fs){sqlite3_bind_int64(s,1,id);sqlite3_bind_text(s,2,f.page_address.c_str(),-1,SQLITE_TRANSIENT);sqlite3_bind_int64(s,3,f.start);sqlite3_bind_int64(s,4,f.end);sqlite3_bind_text(s,5,f.text.c_str(),-1,SQLITE_TRANSIENT);sqlite3_bind_double(s,6,f.lexical_score);sqlite3_bind_double(s,7,f.language_score);sqlite3_bind_text(s,8,f.method.c_str(),-1,SQLITE_TRANSIENT);sqlite3_bind_text(s,9,f.classification.c_str(),-1,SQLITE_TRANSIENT);sqlite3_bind_int64(s,10,f.word_count);sqlite3_bind_double(s,11,f.grammar_score);sqlite3_bind_double(s,12,f.ngram_score);sqlite3_bind_double(s,13,f.completeness_score);if(f.has_semantic_score)sqlite3_bind_double(s,14,f.semantic_score);else sqlite3_bind_null(s,14);sqlite3_bind_text(s,15,f.scoring_model.c_str(),-1,SQLITE_TRANSIENT);sqlite3_bind_text(s,16,f.scoring_version.c_str(),-1,SQLITE_TRANSIENT);sqlite3_bind_text(s,17,f.validation_method.c_str(),-1,SQLITE_TRANSIENT);sqlite3_bind_text(s,18,f.source_backend.c_str(),-1,SQLITE_TRANSIENT);sqlite3_bind_text(s,19,f.source_mode.c_str(),-1,SQLITE_TRANSIENT);sqlite3_bind_text(s,20,f.verification_status.c_str(),-1,SQLITE_TRANSIENT);check(sqlite3_step(s),db_);sqlite3_reset(s);}sqlite3_finalize(s);if(own)check(sqlite3_exec(db_,"COMMIT",nullptr,nullptr,nullptr),db_);}
void Storage::checkpoint(std::int64_t id,std::uint64_t done,double elapsed,const std::string&status){sqlite3_stmt*s;check(sqlite3_prepare_v2(db_,"INSERT INTO checkpoints VALUES(?,?,CURRENT_TIMESTAMP) ON CONFLICT(experiment_id) DO UPDATE SET last_completed_work_unit=excluded.last_completed_work_unit,updated_at=CURRENT_TIMESTAMP",-1,&s,nullptr),db_);sqlite3_bind_int64(s,1,id);sqlite3_bind_int64(s,2,done);check(sqlite3_step(s),db_);sqlite3_finalize(s);check(sqlite3_prepare_v2(db_,"UPDATE experiments SET pages_scanned=?,elapsed_seconds=?,status=?,completed_at=CASE WHEN ?='completed' THEN CURRENT_TIMESTAMP ELSE completed_at END WHERE id=?",-1,&s,nullptr),db_);sqlite3_bind_int64(s,1,done);sqlite3_bind_double(s,2,elapsed);sqlite3_bind_text(s,3,status.c_str(),-1,SQLITE_TRANSIENT);sqlite3_bind_text(s,4,status.c_str(),-1,SQLITE_TRANSIENT);sqlite3_bind_int64(s,5,id);check(sqlite3_step(s),db_);sqlite3_finalize(s);}
Experiment Storage::experiment(std::int64_t id)const{sqlite3_stmt*s;check(sqlite3_prepare_v2(db_,"SELECT id,backend,seed,configuration,status,pages_scanned,elapsed_seconds FROM experiments WHERE id=?",-1,&s,nullptr),db_);sqlite3_bind_int64(s,1,id);if(sqlite3_step(s)!=SQLITE_ROW){sqlite3_finalize(s);throw std::runtime_error("experiment not found");}Experiment e{id,reinterpret_cast<const char*>(sqlite3_column_text(s,1)),static_cast<std::uint64_t>(sqlite3_column_int64(s,2)),reinterpret_cast<const char*>(sqlite3_column_text(s,3)),reinterpret_cast<const char*>(sqlite3_column_text(s,4)),static_cast<std::uint64_t>(sqlite3_column_int64(s,5)),sqlite3_column_double(s,6)};sqlite3_finalize(s);return e;}
static std::vector<Finding> query(sqlite3*db,const char*sql,std::int64_t id,std::size_t limit,bool bindId){sqlite3_stmt*s;check(sqlite3_prepare_v2(db,sql,-1,&s,nullptr),db);int p=1;if(bindId)sqlite3_bind_int64(s,p++,id);sqlite3_bind_int64(s,p,static_cast<sqlite3_int64>(limit));std::vector<Finding>v;while(sqlite3_step(s)==SQLITE_ROW){Finding f;f.page_address=reinterpret_cast<const char*>(sqlite3_column_text(s,0));f.start=sqlite3_column_int64(s,1);f.end=sqlite3_column_int64(s,2);f.text=reinterpret_cast<const char*>(sqlite3_column_text(s,3));f.lexical_score=sqlite3_column_double(s,4);f.language_score=sqlite3_column_double(s,5);f.method=reinterpret_cast<const char*>(sqlite3_column_text(s,6));f.classification=reinterpret_cast<const char*>(sqlite3_column_text(s,7));f.word_count=sqlite3_column_int64(s,8);f.grammar_score=sqlite3_column_double(s,9);f.ngram_score=sqlite3_column_double(s,10);f.completeness_score=sqlite3_column_double(s,11);f.has_semantic_score=sqlite3_column_type(s,12)!=SQLITE_NULL;if(f.has_semantic_score)f.semantic_score=sqlite3_column_double(s,12);f.scoring_model=reinterpret_cast<const char*>(sqlite3_column_text(s,13));f.scoring_version=reinterpret_cast<const char*>(sqlite3_column_text(s,14));f.validation_method=reinterpret_cast<const char*>(sqlite3_column_text(s,15));f.source_backend=reinterpret_cast<const char*>(sqlite3_column_text(s,16));f.source_mode=reinterpret_cast<const char*>(sqlite3_column_text(s,17));f.verification_status=reinterpret_cast<const char*>(sqlite3_column_text(s,18));v.push_back(std::move(f));}sqlite3_finalize(s);return v;}
static constexpr const char* fields="page_address,start_offset,end_offset,extracted_text,lexical_score,language_score,detection_method,classification,word_count,grammar_score,ngram_score,completeness_score,semantic_score,scoring_model,scoring_version,validation_method,source_backend,source_mode,verification_status";
std::vector<Finding> Storage::findings(std::int64_t id,std::size_t n,const std::string&type,const std::string&sort)const{if(type!="all"&&type!="sentence"&&type!="word"&&type!="phrase")throw std::runtime_error("type must be all|sentence|word|phrase");if(sort!="score"&&sort!="length")throw std::runtime_error("sort must be score|length");std::string method=type=="word"?"dictionary":type;std::string where=type=="all"?"":" AND detection_method=\'"+method+"\'";std::string order=sort=="score"?"language_score DESC,id":"length(extracted_text) DESC,id";std::string q="SELECT "+std::string(fields)+" FROM findings WHERE experiment_id=?"+where+" ORDER BY "+order+" LIMIT ?";return query(db_,q.c_str(),id,n,true);}
std::vector<Finding> Storage::recent_findings(std::size_t n)const{std::string q="SELECT "+std::string(fields)+" FROM findings ORDER BY language_score DESC LIMIT ?";return query(db_,q.c_str(),0,n,false);}
}
